def _page_ordinal(page_id: str) -> int:
    """Trailing integer of a page id (``"page-12"`` → ``12``); 0 when absent."""
    digits = ""
    for char in reversed(page_id):
        if not char.isdigit():
            break
        digits = char + digits
    return int(digits) if digits else 0

