    ) -> None:
        self.settings = deepcopy(dict(settings or {}))
        self.provider_bindings = deepcopy(dict(provider_bindings or {}))
        self.constraint_snapshot_ref = constraint_snapshot_ref
        self.context_policy = deepcopy(dict(context_policy or {}))

    def freeze(
        self,
