class ContextChunk:
    """A provider-sized slice of the bundle; every chunk carries its own
    primary regions so outputs can be mapped back (TASK-002 §4)."""

    entries: tuple[ContextEntry, ...] = ()

    @property
    def primary_region_ids(self) -> frozenset[str]:
        return frozenset(e.region_id for e in self.entries if e.role == PRIMARY)

class ContextBundle:
    mode: str  # single_page | max_pages | webtoon
    entries: tuple[ContextEntry, ...]
    chunks: tuple[ContextChunk, ...]
    budget_used: int
    token_budget: int | None
    _write_scope: frozenset[tuple[str, str]] = field(repr=False)

    @property
    def write_scope(self) -> frozenset[tuple[str, str]]:
        """目标写回范围 (D06 §14): only these (page_id, region_id) pairs may
        be updated by a Step consuming this bundle."""

        return self._write_scope

    @property
    def context_scope(self) -> frozenset[tuple[str, str]]:
        return frozenset((e.page_id, e.region_id) for e in self.entries)

    def primary_entries(self) -> tuple[ContextEntry, ...]:
        return tuple(e for e in self.entries if e.role == PRIMARY)

    def provenance(self) -> dict:
        """实际上下文 provenance (D06 §13): what was read, in what order."""

        return {
            "mode": self.mode,
            "token_budget": self.token_budget,
            "budget_used": self.budget_used,
            "entries": [
                {
                    "page_id": e.page_id,
                    "page_sort_order": e.page_sort_order,
                    "region_id": e.region_id,
                    "reading_order": e.reading_order,
                    "role": e.role,
                }
                for e in self.entries
            ],
        }

def provenance(self) -> dict:
    """实际上下文 provenance (D06 §13): what was read, in what order."""

    return {
        "mode": self.mode,
        "token_budget": self.token_budget,
        "budget_used": self.budget_used,
        "entries": [
            {
                "page_id": e.page_id,
                "page_sort_order": e.page_sort_order,
                "region_id": e.region_id,
                "reading_order": e.reading_order,
                "role": e.role,
            }
            for e in self.entries
        ],
    }

def _sorted_entries(
    pages: Sequence[PageContextInput],
    *,
    target_page_id: str,
    target_region_ids: frozenset[str],
    included_page_ids: set[str],
) -> tuple[ContextEntry, ...]:
    ordered = sorted(pages, key=lambda p: p.sort_order)
    entries: list[ContextEntry] = []
    for page in ordered:
        if page.page_id not in included_page_ids:
            continue
        for region in sorted(page.regions, key=lambda r: r.reading_order):
            if page.page_id == target_page_id and region.region_id in target_region_ids:
                role = PRIMARY
            else:
                role = CONTEXT
            entries.append(_entry(region, page.page_id, page.sort_order, role))
    return tuple(entries)

def _target_ids(
    target_page: PageContextInput, target_region_ids: Sequence[str] | None
) -> frozenset[str]:
    available = {r.region_id for r in target_page.regions}
    if target_region_ids is None:
        return available
    requested = frozenset(target_region_ids)
    missing = requested - available
    if missing:
        raise ContextBuildError(
            f"target regions not on the target page: {sorted(missing)}"
        )
    if not requested:
        raise ContextBuildError("target_region_ids must not be empty")
    return requested

def _default_estimator(text: str) -> int:
    """First shipped budget unit: 1 token ≈ 1 character (CJK-friendly,
    deterministic, dependency-free). Callers may inject a real tokenizer."""

    return len(text)

def _find_page(ordered: Sequence[PageContextInput], target_page_id: str) -> int:
    for index, page in enumerate(ordered):
        if page.page_id == target_page_id:
            return index
    raise ContextBuildError(f"unknown target page: {target_page_id}")

class TranslationAction:
    """Planner-visible decision for one region's automatic translation."""

    status: str  # translate | skip_policy
    reason: str | None = None

    @property
    def skipped(self) -> bool:
        return self.status == SKIP_POLICY

def decide_sfx_translation(region_type: str, sfx_policy: str) -> TranslationAction:
    region = RegionType(region_type)
    if region is not RegionType.SFX:
        return TranslationAction(TRANSLATE)
    policy = SfxPolicy(sfx_policy)
    if policy is SfxPolicy.TRANSLATE:
        return TranslationAction(TRANSLATE)
    # skip and manual both keep the original artwork text for automatic runs
    # (TASK-002 §7.2); a manual SFX needs an explicit user final + render
    # request before any image processing, which is not this step.
    return TranslationAction(SKIP_POLICY, SFX_SKIP_REASON)

class EffectiveConstraintSnapshot:
    """Frozen, read-only view of the constraints governing one Run."""

    run_id: str
    frozen_at: str
    _terms: Mapping[str, EffectiveConstraint] = field(repr=False)
    _do_not_translate: frozenset[str] = field(repr=False)

    def lookup(self, normalized_key: str) -> EffectiveConstraint | None:
        return self._terms.get(normalized_key)

    def terminology(self) -> Mapping[str, EffectiveConstraint]:
        return self._terms

    def do_not_translate(self) -> frozenset[str]:
        return self._do_not_translate

    def provenance(self) -> tuple[dict, ...]:
        """Per-term provenance: which constraint revision supplied the value."""

        return tuple(
            {
                "normalized_key": key,
                "constraint_id": value.constraint_id,
                "revision_id": value.revision_id,
                "scope_type": value.scope_type.value,
                "locked": value.locked,
            }
            for key, value in self._terms.items()
        )

def provenance(self) -> tuple[dict, ...]:
    """Per-term provenance: which constraint revision supplied the value."""

    return tuple(
        {
            "normalized_key": key,
            "constraint_id": value.constraint_id,
            "revision_id": value.revision_id,
            "scope_type": value.scope_type.value,
            "locked": value.locked,
        }
        for key, value in self._terms.items()
    )

def freeze_constraints(
    constraints: Sequence,
    *,
    run_id: str,
    frozen_at: str,
    book_id: str | None = None,
    chapter_id: str | None = None,
) -> EffectiveConstraintSnapshot:
    merged = merge_constraints(constraints, book_id=book_id, chapter_id=chapter_id)
    terms = {k: v for k, v in merged.items() if v.constraint_kind is ConstraintKind.TERMINOLOGY}
    do_not_translate = frozenset(
        k for k, v in merged.items() if v.constraint_kind is ConstraintKind.DO_NOT_TRANSLATE
    )
    return EffectiveConstraintSnapshot(
        run_id=run_id,
        frozen_at=frozen_at,
        _terms=MappingProxyType(terms),
        _do_not_translate=do_not_translate,
    )

class OutputMappingError(Exception):
    """Provider output violates the request's target mapping
    (TASK-002 §4 OUTPUT_MAPPING_MISMATCH semantics)."""

class TargetSlot:
    page_id: str
    region_id: str

class TranslateStepResult:
    """D06 §18.2 outputs — machine translations + full provenance."""

    translations: Mapping[str, str]
    skipped: tuple[SkippedTarget, ...]
    model: str
    request_options: Mapping
    context_provenance: dict
    term_provenance: tuple[dict, ...]

    def translation_for(self, region_id: str) -> str | None:
        return self.translations.get(region_id)

def build_provider_request(
    *,
    bundle: ContextBundle,
    snapshot: EffectiveConstraintSnapshot,
    tm_matches: tuple[TmMatch, ...] = (),
    model: str = "",
    options: Mapping | None = None,
    targets: tuple[TargetSlot, ...] | None = None,
) -> TranslationRequest:
    """Compose prompt + glossary + TM references + write targets."""

    primary_ids = {entry.region_id for entry in bundle.primary_entries()}
    if targets is None:
        targets = tuple(
            TargetSlot(entry.page_id, entry.region_id)
            for entry in bundle.primary_entries()
        )
    else:
        unknown = [t for t in targets if t.region_id not in primary_ids]
        if unknown:
            raise OutputMappingError(
                f"targets outside the bundle's write scope: {unknown}"
            )
    glossary = tuple(
        {
            "normalized_key": key,
            "source_term": value.source_term,
            "target_term": value.target_term,
            "locked": value.locked,
        }
        for key, value in snapshot.terminology().items()
    )
    tm_references = tuple(
        {
            "source_text": match.entry.source_text,
            "target_text": match.entry.target_text,
            "match_type": match.match_type,
            "similarity": match.similarity,
        }
        for match in tm_matches
    )
    lines: list[str] = []
    for entry in bundle.entries:
        tag = "TARGET" if entry.role == PRIMARY else "CONTEXT"
        lines.append(f"[{tag}] {entry.text}")
    prompt = "\n".join(lines)
    return TranslationRequest(
        model=model,
        prompt=prompt,
        term_glossary=glossary,
        do_not_translate=frozenset(snapshot.do_not_translate()),
        tm_references=tm_references,
        targets=targets,
        options=dict(options or {}),
        context_provenance=bundle.provenance(),
    )

def map_provider_output(
    request: TranslationRequest, outputs: Mapping[str, str]
) -> dict[str, str]:
    """Every provider item must map onto a requested primary region; unknown,
    duplicate or missing mappings fail the step (TASK-002 §4). Mapping keys
    are region ids, so duplicates cannot occur; unknown keys (e.g. context
    regions) and missing targets raise."""

    expected = {slot.region_id for slot in request.targets}
    unknown = sorted(set(outputs) - expected)
    if unknown:
        raise OutputMappingError(
            f"output outside the write scope (AC-TRANS-003): {unknown}"
        )
    missing = sorted(expected - set(outputs))
    if missing:
        raise OutputMappingError(f"missing output for targets: {missing}")
    return dict(outputs)

def _regroup(bundle: ContextBundle, translate_entries) -> ContextBundle:
    """Bundle narrowed to the translatable primaries; context untouched."""

    keep_ids = {entry.region_id for entry in translate_entries}
    entries = tuple(
        entry
        for entry in bundle.entries
        if entry.role == CONTEXT or entry.region_id in keep_ids
    )
    return replace(
        bundle,
        entries=entries,
        chunks=(ContextChunk(entries),),
    )

