def find_by_source_hash(
    self, source_hash: str, *, scope_type: TmScope, book_id: str | None
) -> list[TranslationMemoryEntry]: ...

def _similarity(a: str, b: str) -> float:
    if not a or not b:
        return 0.0
    return difflib.SequenceMatcher(None, a, b).ratio()

