                return DevicePlan(DEVICE_GPU, requested, device_info=info)
            if not supports_cpu_fallback:
                raise DeviceUnavailable(
                    f"GPU required but unavailable: {info.detail}",
                    provider_id="",
                    stage="device",
                )
