    for y, row in enumerate(self.rows):
        for x, cell in enumerate(row):
            if cell:
                xs.append(x)
                ys.append(y)
    if not xs:
        return None
    return (min(xs), min(ys), max(xs) + 1, max(ys) + 1)

def covers(self, inner: "BooleanMask") -> bool:
    if (inner.width, inner.height) != (self.width, self.height):
        return False
    return all(
