        exportFinished / exportFailed so QML never blocks."""
        if self._running:
            return
        request = self._build_request()
        if request is None:
            self._fail("没有可导出的页面；请先打开一个章节")
            return
        self._cancel_event.clear()
        self._running = True
        self._status = "正在导出…"
        self.changed.emit()

