    @Slot()
    def saveInspector(self) -> None:
        if not self._inspector_dirty or self._inspector_region_id is None:
            return
        if self._translation_editor is None:
            self._record_command_error("no translation editor bound", stage="editor")
            return
        self._translation_editor.save_manual_translation(
            self._inspector_region_id, self._inspector_text
        )
        self._inspector_saved_text = self._inspector_text
        self._set_dirty(False)

    @Slot()
    def discardInspector(self) -> None:
        self._inspector_text = self._inspector_saved_text
        self._set_dirty(False)

    @Slot(float, float, float, float)
    def createRectangle(
        self, nx0: float, ny0: float, nx1: float, ny1: float
    ) -> None:
        """Persist an axis-aligned region from two normalized canvas corners.

        Corner order is not a contract: dragging left or up is as valid as
        dragging right or down, so the converter takes min/max itself.
        """
        self._create_region_geometry([(nx0, ny0), (nx1, ny1)])

    @Slot(str)
    def createPolygon(self, pointsJson: str) -> None:
        """Persist a free polygon from a JSON ``[[nx, ny], ...]`` ring.

        Points cross the seam as a string on purpose: a QVariantList would
        leave the element types to Qt's coercion rules, and a ring is only
        meaningful as pairs of floats.
        """
        points = self._parse_normalized_points(pointsJson)
        if points is None:
            self._record_command_error(
                "polygon points are not a [[x, y], ...] list", stage="editor"
            )
            return
        self._create_region_geometry(points)

    @staticmethod
    def _parse_normalized_points(
        points_json: str,
    ) -> list[tuple[float, float]] | None:
        try:
            raw = json.loads(points_json)
            points = [(float(pair[0]), float(pair[1])) for pair in raw]
        except (ValueError, TypeError, KeyError, IndexError):
            return None
        # Fewer than three points is not a ring. Two would otherwise be read
        # as a rectangle by the converter and persist a box nobody drew.
        return points if len(points) >= 3 else None

    def _create_region_geometry(self, points: list[tuple[float, float]]) -> None:
        """Shared commit path: validate first, write once, never raise to QML."""

        if self._region_creator is None:
            self._record_command_error("no region creator bound", stage="editor")
            return
        page_id = self._viewer_page_id
        if page_id is None:
            self._record_command_error("no page selected", stage="editor")
            return
        row = self._pages.get(page_id, {})
        try:
            geometry = normalized_to_page_geometry(
                points, row.get("width", 0), row.get("height", 0)
            )
        except RegionCanvasError as error:
            # The exception object, not just its text: _record_command_error
            # puts ``code`` on commandErrorText so a rejected drag is
            # diagnosable as a geometry problem instead of a mystery no-op.
            self._record_command_error(error, stage="editor")
            return
        region = self._region_creator.create_region(page_id, geometry)
        # A drawn region should show up in the Inspector immediately — but not
        # by discarding translation text the user typed and never saved.
        if not self._inspector_dirty:
            self._apply_inspector_region(region.region_id)
        self.inspectorChanged.emit()

    @Slot(str)
    def deleteRegion(self, region_id: str) -> None:
        """Remove a mis-drawn region.

        A canvas that commits on release without a way back leaves the user
        looking at a box they cannot get rid of. The repository soft-deletes,
        and ``list_regions`` already filters deleted rows, so the overlay
        loses the box on the next refresh with no extra broadcast.
        """

        if self._region_deleter is None:
            self._record_command_error("no region deleter bound", stage="editor")
            return
        if not region_id:
            self._record_command_error("no region selected", stage="editor")
            return
        self._region_deleter.delete_region(region_id)
        if self._inspector_region_id == region_id:
            self._inspector_region_id = None
            self._inspector_saved_text = ""
            self._inspector_text = ""
            self._set_dirty(False)
        self.inspectorChanged.emit()

    def _set_dirty(self, dirty: bool) -> None:
        if self._inspector_dirty != dirty:
            self._inspector_dirty = dirty
            self.inspectorDirtyChanged.emit()

    def _navigate(self, target: dict) -> bool:
        """Dirty navigation guard: switching page/region with unsaved
        inspector edits asks save/discard/cancel first (D05 §55)."""

        if not self._inspector_dirty:
            return True
        self._pending_navigation = target
        self.inspectorDirtyConfirmRequested.emit(target)
        return False

    @Slot(str)
    def resolveDirtyConfirm(self, action: str) -> None:
        """Finish a guarded navigation: save / discard / cancel."""

        target = self._pending_navigation
        self._pending_navigation = None
        if action == "cancel" or target is None:
            return
        if action == "save":
            self.saveInspector()
        else:
            self.discardInspector()
        if target["kind"] == "page":
            self._apply_viewer_page(target["page_id"])
        else:
            self._apply_inspector_region(target["region_id"])

